import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"節","description":"焦氏易林注 - 節","frontmatter":{"title":"節","description":"焦氏易林注 - 節"},"headers":[],"relativePath":"zh/classics/jiaoyilin/060.md","filePath":"zh/classics/jiaoyilin/060.md"}'),l={name:"zh/classics/jiaoyilin/060.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="節" tabindex="-1">節 <a class="header-anchor" href="#節" aria-label="Permalink to “節”">​</a></h1><h3 id="節-1" tabindex="-1">節 <a class="header-anchor" href="#節-1" aria-label="Permalink to “節”">​</a></h3><h3 id="節之乾" tabindex="-1">節之乾 <a class="header-anchor" href="#節之乾" aria-label="Permalink to “節之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>虎豹怒咆，慎戒外憂。上下俱搔，士民無聊。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用《節》象。艮為虎豹，震怒。坎為憂，艮為上，震為下、為士，坎為民。</p><h3 id="節之坤" tabindex="-1">節之坤 <a class="header-anchor" href="#節之坤" aria-label="Permalink to “節之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>探穴得雛，鳩鵲俱來，使我心憂。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此仍用《節》象。艮為巢，艮手，故曰探巢。震為鵲、為雛。坎為心憂。</p><h3 id="節之屯" tabindex="-1">節之屯 <a class="header-anchor" href="#節之屯" aria-label="Permalink to “節之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>日望一食，常恐不足，祿命寡薄。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>艮為日、為望，震為食，坤虗，故不足。乾為祿，巽為命，坤為寡，坎為薄，乾巽伏，故曰祿命寡薄。</p><h3 id="節之蒙" tabindex="-1">節之蒙 <a class="header-anchor" href="#節之蒙" aria-label="Permalink to “節之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>良馬疾走，千里一宿。逃難它鄉，誰能追復。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>震為馬、為走，下坎，故曰疾走。坤為千里、為宿，坎數一，故曰一宿。坎為難，坤為鄉、為蛇，故曰它鄉。它蛇同字，它鄉有毒，故不能追復。震為追、為歸，故曰追復。○逃難，汲古作離逃，茲依宋元本。</p><h3 id="節之需" tabindex="-1">節之需 <a class="header-anchor" href="#節之需" aria-label="Permalink to “節之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>鵲巢鳩成，上下不親。外內乖畔，子走失願。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>互離為巢、為鳩，《詩》維鵲有巢，維鳩居之。鵲巢鳩成者，言鵲營巢成，為鳩居也。坎水性下，乾陽上升，故曰不親。○鳩成，宋元本作鳥城，汲古作鳩城，茲從局本。外內，汲古作內外，依宋元本。失願，宋元本作矢頑，依汲古。</p><h3 id="節之訟" tabindex="-1">節之訟 <a class="header-anchor" href="#節之訟" aria-label="Permalink to “節之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>雲龍集會，征討西戎。招邊定眾，誰敢當鋒。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>坎雲，乾龍，坎為積，故曰集會。伏震為征討，坤為戎，坎為西，故曰西戎。坤為邊、為眾，坤安，故曰定。坎為矢，故曰鋒。</p><h3 id="節之師" tabindex="-1">節之師 <a class="header-anchor" href="#節之師" aria-label="Permalink to “節之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>春多膏澤，夏潤優渥。稼穡成熟，畝獲百斛。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《明夷》。</p><h3 id="節之比" tabindex="-1">節之比 <a class="header-anchor" href="#節之比" aria-label="Permalink to “節之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>僮妾獨宿，長女未室，利無所得。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>詳《豫》之《益》。</p><h3 id="節之小畜" tabindex="-1">節之小畜 <a class="header-anchor" href="#節之小畜" aria-label="Permalink to “節之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>四野不安，東西為患。退身止足，無出邦域。乃得全完，賴其生福。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《睽》。野，宋元本作亂。第三句宋元本作退止我足，茲依汲古。</p><h3 id="節之履" tabindex="-1">節之履 <a class="header-anchor" href="#節之履" aria-label="Permalink to “節之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>長寧履福，安我百國。嘉賓上堂，與季同床。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。震為履、為福，坤為安、為百國，故曰安我百國。震為賓，艮為堂、為季、為床。○履福，宋元本作理福，依汲古。</p><h3 id="節之泰" tabindex="-1">節之泰 <a class="header-anchor" href="#節之泰" aria-label="Permalink to “節之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>騏驥綠耳，章明造父。伯夙奏獻，衰續厥緒。佐文成霸，為晉元輔。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>詳《革》之《夬》。驥綠，宋元本作驎騄。伯夙奏獻，宋元本作伯夙成季，汲古作夙伯奏獻。宋元無第四句。第五句作共成霸功，茲依汲古。奏，進也，言進仕獻公也。祇伯夙依宋元。</p><h3 id="節之否" tabindex="-1">節之否 <a class="header-anchor" href="#節之否" aria-label="Permalink to “節之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>張陳嘉謨，贊成漢都。主歡民喜，其樂休休。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>伏震為張、為陳、為嘉，坤為謀、為都、為水，故曰漢都。坤為民，震為主、為歡樂，言張良陳平主張都關中也。</p><h3 id="節之同人" tabindex="-1">節之同人 <a class="header-anchor" href="#節之同人" aria-label="Permalink to “節之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>大面長頭，來解君憂。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>乾為頭，互巽，故曰長頭。○汲古下多遺吾福善，與我嘉惠二句，依宋元本。</p><h3 id="節之大有" tabindex="-1">節之大有 <a class="header-anchor" href="#節之大有" aria-label="Permalink to “節之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>畏昏不行，待旦昭明。燎獵受福，老賴其慶。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>詳《夬》之《損》。</p><h3 id="節之謙" tabindex="-1">節之謙 <a class="header-anchor" href="#節之謙" aria-label="Permalink to “節之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>伯去我東，首髪如蓬。長夜不寐，輾轉空床。內懷惆悵，憂摧肝腸。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《姤》之《遯》。宋元本無下二句，第四句作憂繫心胸，茲依汲古。</p><h3 id="節之豫" tabindex="-1">節之豫 <a class="header-anchor" href="#節之豫" aria-label="Permalink to “節之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>朽條腐索，不堪施用。安靜候時，以待親知。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>伏巽為索、為腐，故曰朽條腐索。艮為時，坤為安，艮止，故曰候時。</p><h3 id="節之隨" tabindex="-1">節之隨 <a class="header-anchor" href="#節之隨" aria-label="Permalink to “節之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>比目四翼，相倚為福。薑氏季女，與君合德。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>詳《渙》之《明夷》。女，宋元本作氏，非，依汲古。</p><h3 id="節之蠱" tabindex="-1">節之蠱 <a class="header-anchor" href="#節之蠱" aria-label="Permalink to “節之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>履階升墀，高登崔嵬。福祿洋溢，依天之威。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>艮為階墀，震為履、為登，巽為高。震為福祿。艮為天。</p><h3 id="節之臨" tabindex="-1">節之臨 <a class="header-anchor" href="#節之臨" aria-label="Permalink to “節之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>奢淫吝嗇，神所不福。靈祇憑怒，鬼瞰其室。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>坤多，故曰奢。坤閉，故曰吝嗇。震為神、為福、為靈祇、為怒。坤為鬼，伏艮為室、為觀，故曰鬼瞰其室。○吝，宋元本作愛，瞰作障。靈祇，元本作祇靈，均依汲古。</p><h3 id="節之觀" tabindex="-1">節之觀 <a class="header-anchor" href="#節之觀" aria-label="Permalink to “節之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>大步上車，南到喜家。送我狐裘，與福載來。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>伏震為步，坤為車，震為南、為喜，坤為家、為狐。○上，宋元本作小，狐作豹，茲依汲古。</p><h3 id="節之噬嗑" tabindex="-1">節之噬嗑 <a class="header-anchor" href="#節之噬嗑" aria-label="Permalink to “節之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>南行西步，失次後舍。乾候野井，昭公失居。與彼作期，不覺至夜。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為東，坎為西，震為後，艮為舍，坎失，故曰失次後舍。震為諸侯，上離，故曰乾候。坎為井，艮為野，故曰野井。震為公，上離，故曰昭公。坎為夜，言照公為季氏所逐，次於乾候野井也。○舍，汲古訛含，依宋元本。彼，元本作陂，覺作真，依宋本、汲古。三四與五六兩句宋元本倒置，不協，依汲古。</p><h3 id="節之賁" tabindex="-1">節之賁 <a class="header-anchor" href="#節之賁" aria-label="Permalink to “節之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>喜樂踴躍，來迎名家。鵲巢百兩，以成嘉福。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震為踴躍、為樂。艮為名、為家，故曰名家。震為鵲，艮為巢，震為車，故曰百兩。《詩周南》維鵲有巢，維鳩居之。之子於歸，百兩御之。艮為成，震為嘉福。○踴，宋元本作拚。名家，汲古作歡客，依宋元本。宋元本第四句作獲利養福，均依汲古，惟汲古下多多獲利益四字，茲從宋元本刪。名家與大家同，與福亦協。</p><h3 id="節之剝" tabindex="-1">節之剝 <a class="header-anchor" href="#節之剝" aria-label="Permalink to “節之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>非理所求，誰敢相與。往來不獲，徒勞道路。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為求，坤為理，艮止，故不與。艮為道路，離虗，故不獲而徒勞也。坤役萬物，故亦曰勞。○所求，宋元本作後來，依汲古。</p><h3 id="節之復" tabindex="-1">節之復 <a class="header-anchor" href="#節之復" aria-label="Permalink to “節之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>北虜匈奴，數侵邊境。左衽為長，國猶未慶。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>坤為北、為夷，故曰匈奴。坤為境，震為侵、為左、為衽、為長，坤為國。末句疑有訛字。</p><h3 id="節之無妄" tabindex="-1">節之無妄 <a class="header-anchor" href="#節之無妄" aria-label="Permalink to “節之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>狂不以理，伐乃無名。縱獲臣子，伯功不成。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為征伐、為子、為伯，艮為臣、為拘系，故曰獲。○汲古作&quot;續事康域，針折不成。嬰兒短舌，說辭無名&quot;，茲依宋元本。</p><h3 id="節之大畜" tabindex="-1">節之大畜 <a class="header-anchor" href="#節之大畜" aria-label="Permalink to “節之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>景星照堂，麟游鳳翔。仁施大行，頌聲作興。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>詳《豫》之《節》。</p><h3 id="節之頤" tabindex="-1">節之頤 <a class="header-anchor" href="#節之頤" aria-label="Permalink to “節之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>文明之世，銷鋒鑄耜。以道順民，百王不易。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>坤為世、為文，艮為明，故曰文明之世。艮為鋒、為耜，艮火，故曰銷鋒鑄耜。坤為民、為順，震為大塗，故曰以道順民。震為王，坤為百，艮止，故不易。○耜，宋元本作鏑，依汲古。民，汲古作昌，依宋元本。</p><h3 id="節之大過" tabindex="-1">節之大過 <a class="header-anchor" href="#節之大過" aria-label="Permalink to “節之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>鳥飛無羽，雞鬬折距。徒自長嗟，誰肯為侶。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>震為鳥、為飛，巽寡髪，故曰無羽。巽為雞，震為距，震伏不見，故曰折距。巽為長，兌口為嘆。巽寡，故無侶。</p><h3 id="節之坎" tabindex="-1">節之坎 <a class="header-anchor" href="#節之坎" aria-label="Permalink to “節之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>群隊虎狼，嚙彼牛羊。道路不通，妨農害商。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>互艮為虎狼，正反艮，故曰群隊。伏兌為嚙，離為牛，兌為羊。震為道路，坎塞，故不通。震為商旅，坎為害。</p><h3 id="節之離" tabindex="-1">節之離 <a class="header-anchor" href="#節之離" aria-label="Permalink to “節之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>商伯沈酒，庶兄奔走。淫女盪夫，仁德並孤。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>伏震為商、為伯，坎為酒，故曰商伯沈酒。震為兄，坎為眾，故曰庶兄。庶，眾也。震為奔走，言商紂沈湎於酒，庶兄微子抱祭器奔周也。兌為媚，正反兌，故曰淫女，謂妲己也。伏坎為未，坎水，故曰盪夫，謂紂也。震為仁德，坎為孤。</p><h3 id="節之咸" tabindex="-1">節之咸 <a class="header-anchor" href="#節之咸" aria-label="Permalink to “節之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>三狸搏鼠，遮遏前後。當此之時，不能脫走。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>通《損》。震為狸，數三，故曰三狸。艮為鼠，故曰三狸搏鼠。艮為前，震為後，二至上正反艮，艮止，故曰遮遏前後，不能脫走。</p><h3 id="節之恒" tabindex="-1">節之恒 <a class="header-anchor" href="#節之恒" aria-label="Permalink to “節之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>陶叔孔圉，不處亂國。初雖未萌，後受慶福。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>陶叔，謂陶朱公，去越適齊，以避勾踐。孔圉未詳。按：《史記孔子世家》孔防叔畏華氏之亂，奔魯。疑圉或防叔之名。恆通益。艮為叔，艮火，故曰陶叔。震為孔，艮止，故曰孔圉。坤為國、為亂，震為福慶、為後。萌疑為明字。</p><h3 id="節之遯" tabindex="-1">節之遯 <a class="header-anchor" href="#節之遯" aria-label="Permalink to “節之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>奮翅鼓翼，翱翔外國。逍遙北域，不入溫室。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>伏震為翼，坤為國、為北。本卦艮為室，艮火，故曰溫室。</p><h3 id="節之大壯" tabindex="-1">節之大壯 <a class="header-anchor" href="#節之大壯" aria-label="Permalink to “節之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>德音孔博，升在王室。八極蒙佑，受其福祿。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震為德、為音、為孔、為升、為王，伏艮為室，伏坤數八，故曰八極蒙佑。乾為福祿。</p><h3 id="節之晉" tabindex="-1">節之晉 <a class="header-anchor" href="#節之晉" aria-label="Permalink to “節之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>當變立權，摘解患難。渙然冰釋，大國以安。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>詳《升》之《震》。渙，宋元本作霍，依汲古。</p><h3 id="節之明夷" tabindex="-1">節之明夷 <a class="header-anchor" href="#節之明夷" aria-label="Permalink to “節之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>羽動角，甘雨續。草木茂，年歲熟。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坎為冬，故曰羽。《月令》冬月其音羽。震為春，故曰角。《月令》春月其音角。羽動角者，言羽音發動，以後角音繼之，至春而有甘雨也。坎為雨，震為草木，坤為年歲，三字句。</p><h3 id="節之家人" tabindex="-1">節之家人 <a class="header-anchor" href="#節之家人" aria-label="Permalink to “節之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>天所佑助，福來禍去，君王何憂。此用節象。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>艮為天，震為福，在內，故曰福來。坎為禍，在外，故曰禍去。震為君王，坎為憂，禍去，故不憂。</p><h3 id="節之睽" tabindex="-1">節之睽 <a class="header-anchor" href="#節之睽" aria-label="Permalink to “節之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>方喙宣口，聖智仁厚。釋解倒懸，唐國大安。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《噬嗑》。</p><h3 id="節之蹇" tabindex="-1">節之蹇 <a class="header-anchor" href="#節之蹇" aria-label="Permalink to “節之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>葛藟蒙棘，華不得實。讒佞亂政，使恩壅塞。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《中孚》。華，元本作棘，從宋本、汲古。</p><h3 id="節之解" tabindex="-1">節之解 <a class="header-anchor" href="#節之解" aria-label="Permalink to “節之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>皇母多恩，字養孝孫。脫於襁褓，成就為君。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>褓，元本作抱，依宋本、汲古。</p><h3 id="節之損" tabindex="-1">節之損 <a class="header-anchor" href="#節之損" aria-label="Permalink to “節之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>積冰不溫，北陸苦寒。露宿多風，君子傷心。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>詳《睽》之《巽》。首句汲古作積冰下濕，依宋本。</p><h3 id="節之益" tabindex="-1">節之益 <a class="header-anchor" href="#節之益" aria-label="Permalink to “節之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>伯夷叔齊，貞廉之師。以德防患，憂禍不存。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《革》之《否》。禍，元本作福，存作凶，茲依宋本、汲古。</p><h3 id="節之夬" tabindex="-1">節之夬 <a class="header-anchor" href="#節之夬" aria-label="Permalink to “節之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>一雌三雄，子不知公。亂我族類，使吾心憒。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>此用《節》象。下兌為一雌，上坎互艮震為三雄，震為子、為公，坎隱，故不知。坎為心。○知，汲古作得，依宋元本。憒，宋元本作憤，依汲古。</p><h3 id="節之姤" tabindex="-1">節之姤 <a class="header-anchor" href="#節之姤" aria-label="Permalink to “節之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>主安多福，天祿所伏。居之寵昌，君子有光。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》之《觀》。</p><h3 id="節之萃" tabindex="-1">節之萃 <a class="header-anchor" href="#節之萃" aria-label="Permalink to “節之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>千歲槐根，身多斧瘢。樹維枯屈，枝葉不出。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>詳《家人》之《乾》。</p><h3 id="節之升" tabindex="-1">節之升 <a class="header-anchor" href="#節之升" aria-label="Permalink to “節之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>周師伐紂，勝殷牧野。甲子平旦，天下大喜。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《噬嗑》。</p><h3 id="節之困" tabindex="-1">節之困 <a class="header-anchor" href="#節之困" aria-label="Permalink to “節之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>日走月步，趨不同舍。夫妻反目，主君失禮。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《同人》。</p><h3 id="節之井" tabindex="-1">節之井 <a class="header-anchor" href="#節之井" aria-label="Permalink to “節之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>宣髪龍叔，為王主國。安土成稷，天下蒙福。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>巽為髪、為白，故曰宣髪。宣，明也。《說卦》巽為寡髪，《釋文》雲本又作宣，黑白雜為宣髪，易林遇巽多謂禿，是讀為寡，茲曰宣是兼讀也。伏震為龍，艮為叔，故曰龍叔。震為王、為主，艮為國、為土、為稷，言築土立稷以祭也。《左傳昭二十九年》共工氏有子曰勾龍，為后土，后土為社；又曰有烈山氏之子曰柱為稷，自夏以上祀之，周棄亦為稷，自商以來祀之，龍叔即勾龍，言勾龍為社稷神，築土為壇祀之，而天下蒙福也。艮為天，震為福。○首句汲古作宣勞就力，依宋元本。</p><h3 id="節之革" tabindex="-1">節之革 <a class="header-anchor" href="#節之革" aria-label="Permalink to “節之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>諷德誦功，美周盛隆。奭旦輔成，光濟沖人。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>詳《明夷》之《蒙》。</p><h3 id="節之鼎" tabindex="-1">節之鼎 <a class="header-anchor" href="#節之鼎" aria-label="Permalink to “節之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>三夜不寢，憂來益甚。戒以危懼，棄其安居。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坤為夜，震數三，故曰三夜。坤為寢，震動，故不寢。坎為憂懼、為險，故曰棄其安居。○寢，元本作寐，其作去，茲依宋本、汲古。</p><h3 id="節之震" tabindex="-1">節之震 <a class="header-anchor" href="#節之震" aria-label="Permalink to “節之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>思願所之，乃今逢時。洗濯故憂，拜其歡來。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>詳《睽》之《艮》。濯，元本作宅，依宋本。拜，汲古作並，依宋元本。</p><h3 id="節之艮" tabindex="-1">節之艮 <a class="header-anchor" href="#節之艮" aria-label="Permalink to “節之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>噂噂囁囁，夜作晝匿。謀議我資，來竊吾室。空盡己財，幾無以食。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>三至上正反震，故曰噂噂囁囁。噂囁，對語也。坎為夜，與震連，故曰夜作。對象離為晝，與巽連，故曰晝匿。巽為伏也。坎為謀議、為竊、為室。○作，汲古作行，竊作攻，均依宋元本。宋元本無下二句，依汲古。</p><h3 id="節之漸" tabindex="-1">節之漸 <a class="header-anchor" href="#節之漸" aria-label="Permalink to “節之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>騂牛無子，鳴於大野。申復陰徵，還歸其母，說以除悔。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>離為牛，坎赤，故曰騂牛。震伏，故曰無子。《左傳》介葛廬來朝，聞牛鳴，曰：是生三犧皆用之矣。艮為大野，震巽同聲，故曰鳴於大野。三四句或謂申者，申後先為幽王所廢，後平王立，後復還，然第三句終難解，疑有訛字。又《比》之《蹇》有申生見母之語，蓋自《虞初志》亡後，故事多遺失，故莫定其是非也。</p><h3 id="節之歸妹" tabindex="-1">節之歸妹 <a class="header-anchor" href="#節之歸妹" aria-label="Permalink to “節之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>王良善御，伯樂知馬。周旋步驟，行中規矩。止息有節，延命壽考。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>詳《遯》之《豫》。○驟，宋元本作趍，依汲古。</p><h3 id="節之豐" tabindex="-1">節之豐 <a class="header-anchor" href="#節之豐" aria-label="Permalink to “節之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>釋然遠咎，避患害早。田獲三狐，以貝為寶。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《謙》。</p><h3 id="節之旅" tabindex="-1">節之旅 <a class="header-anchor" href="#節之旅" aria-label="Permalink to “節之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>仁獸所處，國無凶咎。市賈十倍，復歸惠里。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>艮為獸，互巽，故曰仁獸。艮為國，巽為市賈、為倍，兌數十，故曰十倍。艮為里，伏震為歸、為仁，故曰復歸惠里。</p><h3 id="節之巽" tabindex="-1">節之巽 <a class="header-anchor" href="#節之巽" aria-label="Permalink to “節之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>六目俱視，各欲有志。一言不同，乘戻生訟。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>互離為目，數六，故曰六目。伏坎為心志，兌為言，初至四正反兌，故曰一言不同，乖戻生訟也。○一言，宋元本作心意，非，依汲古。</p><h3 id="節之兌" tabindex="-1">節之兌 <a class="header-anchor" href="#節之兌" aria-label="Permalink to “節之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>傅說王良，驂御四龍。周徑萬里，無有危凶。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>傅說、王良，皆星名。《莊子》傅說相武丁，奄有天下，騎箕尾上，比於列星，故張衡《周天六象賦》雲：天江為太陰之主，傅說奉中闈之祠。《史記天官書》天駟旁一星，曰王良。王良策馬，車騎滿野，故下雲驂御四龍。惟《星經》雲：傅說一星在尾後，主子嗣，茲與王良並言，似亦與天駟有關，抑以傅說騎箕尾箕主風喻馬行之神速歟。兌通艮，艮為星，互震為龍、為驂駕、為周、為萬，艮為里，故曰萬里。互坎為危，震解，故不危。</p><h3 id="節之渙" tabindex="-1">節之渙 <a class="header-anchor" href="#節之渙" aria-label="Permalink to “節之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>伯仲叔季，日暮寢醉。醉醒失明，喪其貝囊，卧拜道旁。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《蠱》。首句宋本作仲伯季叔，非，依汲古。寢醉，宋本、汲古作寢寐，依元本。汲古第三句元本作醒失期明，宋本、汲古作醉醒失明，明與囊旁韻，元本非。卧拜，《謙》之《蠱》作銜卻，拜或為卻之形訛字。</p><h3 id="節之節" tabindex="-1">節之節 <a class="header-anchor" href="#節之節" aria-label="Permalink to “節之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>海為水王，聰聖且明。百流歸德，無有叛逆，常饒優足。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《乾》。汲古下多不利攻玉，所求弗得二句，註雲疑衍，今從宋元本。</p><h3 id="節之中孚" tabindex="-1">節之中孚 <a class="header-anchor" href="#節之中孚" aria-label="Permalink to “節之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>江有寶珠，海多大魚。亟行疾至，可以得財。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>詳《渙》之《需》。可，宋本作所，依元本、汲古。</p><h3 id="節之小過" tabindex="-1">節之小過 <a class="header-anchor" href="#節之小過" aria-label="Permalink to “節之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>遠視千里，不見所持。離婁之明，無益於耳。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>艮為視，艮手為持，艮為光明，兌為耳，伏巽，故不見所持。○持，汲古作視，依宋元本。</p><h3 id="節之既濟" tabindex="-1">節之既濟 <a class="header-anchor" href="#節之既濟" aria-label="Permalink to “節之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>弱足刖跟，不利出門。市賈無嬴，折亡為患。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《鼎》。</p><h3 id="節之未濟" tabindex="-1">節之未濟 <a class="header-anchor" href="#節之未濟" aria-label="Permalink to “節之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>利盡得媒，時不我來。鳴雌深涉，寡宿獨居。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>似用半象，而語特難解。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
